{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-04",
  "sketch": {
    "components": ["Image resize service", "URL fetcher", "Image decoder/resizer"],
    "dataStores": ["Internal databases"],
    "externalServices": ["Arbitrary user-supplied URLs", "Internal metadata service"],
    "trustBoundaries": ["Caller to image service", "Image service to VPC internal network", "Image service to remote internet hosts"],
    "dataClasses": ["credentials", "secrets"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Attacker makes the service fetch the cloud metadata endpoint and steal instance credentials",
      "scenario": "A caller supplies a URL pointing at the link-local metadata endpoint (e.g. 169.254.169.254) or the internal metadata service. The service downloads it from inside the VPC and returns the body to the caller. If the response is returned or leaked through error messages, the attacker obtains instance role credentials or internal configuration and can then act as the service against other VPC resources.",
      "component": "Image resize service URL fetcher",
      "likelihood": 5,
      "impact": 5,
      "evidence": [
        {
          "quote": "The image service accepts a URL parameter, downloads the image from that URL, resizes it and returns it. It runs inside our VPC next to the internal metadata service and databases."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-918", "CWE-200"],
      "plainLanguage": "Someone could ask the service to download a secret internal URL and hand the secrets back to them.",
      "requirement": {
        "title": "Block fetches to link-local, loopback and internal metadata addresses",
        "given": "the image service receives a URL parameter",
        "when": "the resolved destination IP is loopback, link-local (169.254.0.0/16), or any private/internal range including the metadata service",
        "then": "the request is rejected before any connection is made and the caller receives a generic error with no response body or internal detail"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Service used as a proxy to reach internal databases and admin interfaces that callers cannot reach directly",
      "scenario": "Because the fetcher runs inside the VPC next to databases, an attacker supplies URLs targeting internal hosts and ports (http://db:5432/, internal admin consoles, unauthenticated HTTP APIs). Requests arrive with the service's network privileges and source IP, bypassing network segmentation and any IP allowlists, letting the attacker trigger state-changing internal calls they are not authorised to make.",
      "component": "Image resize service network egress",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "It runs inside our VPC next to the internal metadata service and databases."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-918", "CWE-441"],
      "plainLanguage": "The service sits on the trusted network, so attackers can use it as a stepping stone to internal systems.",
      "requirement": {
        "title": "Fetch only through an egress-restricted path with an allowlist",
        "given": "the image service needs to download remote images",
        "when": "an outbound fetch is made",
        "then": "it goes through a dedicated egress proxy or network namespace that permits only public HTTP(S) destinations on ports 80/443 and denies all VPC-internal ranges at the network layer"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Redirects and DNS rebinding bypass URL validation to reach internal targets",
      "scenario": "Even if the supplied URL looks public, the attacker controls a host that 302-redirects to an internal address, or whose DNS record flips to an internal IP between validation and connection (TOCTOU rebinding). The fetch then lands on internal services, defeating naive URL or hostname checks and reproducing the full SSRF impact.",
      "component": "URL fetcher redirect/DNS handling",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "accepts a URL parameter, downloads the image from that URL"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-918", "CWE-350"],
      "plainLanguage": "A public-looking link can quietly point back at internal machines, so checking the text of the URL is not enough.",
      "requirement": {
        "title": "Validate the resolved IP at connect time and control redirects",
        "given": "a URL has passed initial validation",
        "when": "the hostname is resolved and each redirect is followed",
        "then": "the connection pins and re-checks the actual destination IP against the deny list on every hop, limits redirects to a small number, and allows only http/https schemes"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Decompression bomb or huge image exhausts memory and CPU during resize",
      "scenario": "An attacker points the service at a crafted image (e.g. a small file that decodes to tens of thousands of pixels per side, or an endlessly streaming response). Decoding and resizing allocates memory proportional to pixel count, so a few concurrent requests exhaust the container's memory or CPU and the service becomes unavailable to all callers.",
      "component": "Image decoder/resizer",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        {
          "quote": "downloads the image from that URL, resizes it and returns it"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-409", "CWE-400"],
      "plainLanguage": "A tiny file can expand into a giant image and crash the service.",
      "requirement": {
        "title": "Enforce download, dimension and time limits before decoding",
        "given": "a remote response is being fetched for resizing",
        "when": "the byte count, declared pixel dimensions, decode time or output size exceeds configured maximums",
        "then": "the fetch and decode are aborted, buffers are released, and the request fails with a generic error"
      }
    },
    {
      "stride": "Tampering",
      "title": "Malicious image file exploits the decoding library to run code inside the VPC",
      "scenario": "The attacker controls the bytes returned by the URL, so they can serve a malformed image crafted for a known parser vulnerability in the imaging library (or abuse formats with external references such as SVG). Successful exploitation gives code execution in a process that already has network reach to internal databases and the metadata service.",
      "component": "Image decoder/resizer",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "downloads the image from that URL, resizes it and returns it. It runs inside our VPC next to the internal metadata service and databases."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-20", "CWE-94"],
      "plainLanguage": "Attacker-chosen image files are fed to a parser; a bad file could let them run code on an internal server.",
      "requirement": {
        "title": "Decode untrusted images in a sandbox with a format allowlist",
        "given": "downloaded bytes are about to be decoded",
        "when": "the detected content type is not an explicitly allowed raster format, or decoding begins",
        "then": "non-allowed formats (including SVG and other reference-capable formats) are rejected and decoding runs in a sandboxed process with no network access and minimal filesystem access"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Service used as an amplifier to attack third parties and internal hosts",
      "scenario": "Any caller can make the service issue arbitrary outbound requests at high volume, turning it into a reflector for flooding third-party sites or internal hosts, and into a port scanner where response timing and error differences reveal which internal ports are open. The traffic appears to originate from the organisation's VPC, creating abuse and reputational exposure.",
      "component": "URL fetcher",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {
          "quote": "The image service accepts a URL parameter, downloads the image from that URL"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-406", "CWE-918"],
      "plainLanguage": "Attackers can make our server send floods of requests to other machines on their behalf.",
      "requirement": {
        "title": "Authenticate callers and cap outbound fetches per caller",
        "given": "a caller requests an image resize",
        "when": "the caller is unauthenticated or exceeds the configured outbound fetch quota or concurrency limit",
        "then": "the request is refused and no outbound connection is made"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Unauthenticated internal endpoint lets any workload in the network drive fetches",
      "scenario": "The design states no authentication for callers, so any pod, compromised internal service or anyone reaching the VPC network can invoke the resize endpoint and inherit its SSRF reach. There is no attribution of who requested a given fetch, so abuse cannot be traced to a principal and the SSRF controls cannot be scoped per tenant.",
      "component": "Image resize API endpoint",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "The image service accepts a URL parameter, downloads the image from that URL, resizes it and returns it."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-306"],
      "plainLanguage": "Anything on the internal network can call this service, and we cannot tell who asked for what.",
      "requirement": {
        "title": "Require authenticated service identity on the resize endpoint",
        "given": "a request arrives at the image resize endpoint",
        "when": "it does not carry a valid service or user identity",
        "then": "the request is rejected with 401 and accepted requests record the caller identity with the requested URL"
      }
    }
  ]
}
```
